FILE = "neema-ngelime.html"
TITLE = "Neema Ngelime: eight awards for a film that is still in development"
TAG = "Flavor Spotlight"
H1 = "Neema Ngelime"
DEK = "The Tanzanian director turned a doctor's diagnosis into her first feature documentary. Since August, The Ones With the Tempered Flowers has picked up eight awards, in Switzerland, South Africa and Nairobi."
META = "Flavor Spotlight · 3 Nov 2026 · 5 min read"
LEAD = None

BODY = [
("raw", '<figure style="max-width:480px"><img src="img/nn-portrait.jpg" alt="Neema Ngelime"><figcaption>Neema Ngelime<span class="credit">Photo: @futurestorytellers / Instagram</span></figcaption></figure>'),

("p", "Thirty-nine awards were handed out at this year's Durban FilmMart in South Africa. Five of them went to one project: <em>The Ones With the Tempered Flowers</em>, the first feature documentary from Tanzanian director Neema Ngelime. No other project at the market won more than four."),
("p", "Thirteen days later, the same project won again in Nairobi. Back in August, it had already taken two prizes at the Locarno Film Festival's Open Doors programme in Switzerland. That's eight awards in under three months, for a film that is still in development."),

("h2", "The film", "A diagnosis ", "becomes a film"),
("p", "The project started with a doctor's appointment. Ngelime was told that having children might be difficult for her, and that moment became the seed of the film."),
("p", "The documentary follows her as she studies her own body's relationship to herself and to society, and the weight placed on women's bodies in Tanzania. It isn't a conventional fly-on-the-wall documentary. It is participatory and performative, with Ngelime putting herself and her own story in front of the camera."),
("p", "She is making it with Kenyan producer Ivy Kiru, which makes <em>The Ones With the Tempered Flowers</em> a Tanzania–Kenya co-production."),

("h2", "The run", "Eight awards, ", "three countries"),
("p", "The awards so far have come at film markets, where projects still being made are pitched to funders, festivals and co-producers. Most of the prizes are doors rather than trophies: places at major documentary markets in 2027, plus a R100,000 grant from South Africa's National Film and Video Foundation (NFVF)."),
("facts", [
 ("Locarno Open Doors, Aug 2026", "ARTEKino International Award"),
 ("Locarno Open Doors, Aug 2026", "Sørfond Award"),
 ("Durban FilmMart, 12 Oct 2026", "NFVF Best Non-fiction Award, a R100,000 grant"),
 ("Durban FilmMart, 12 Oct 2026", "DOK Leipzig Award: a place at the DOK Co-Pro Market 2027"),
 ("Durban FilmMart, 12 Oct 2026", "Sheffield DocFest Award: an industry pass for 2027 and a free MeetMarket submission"),
 ("Durban FilmMart, 12 Oct 2026", "Movies That Matter Award: accreditation for Movies That Matter 2027"),
 ("Durban FilmMart, 12 Oct 2026", "Visions du Réel Award: a place at the Visions du Réel Market 2027"),
 ("NBO Film Festival, 25 Oct 2026", "NBO Film Festival Development Award"),
]),
("p", "The Nairobi award came at the closing ceremony of the seventh NBO Film Festival, as one of the industry prizes for projects in development."),

("h2", "Before this", "Where her ", "eye comes from"),
("p", "Ngelime is a documentary photographer as well as a filmmaker, and she points both cameras at everyday life. On her Berlinale Talents profile she describes herself as “constantly trying to weave stories about Africa and the African Diaspora through an experimental and feminist lens.”"),
("p", "She studied for a master's at DocNomads, a documentary programme that moves between European cities, and her short films from that time have already travelled. <em>A Country in a Corner</em> was selected for the short documentary competition at IDFA in Amsterdam in 2022."),
("img", "img/nn-ode-poster.jpg", "An Ode to a Time I Loved Bread, poster", "@manyattascreens / Instagram"),
("p", "<em>An Ode to a Time I Loved Bread</em>, an 11-minute short, looks back at her years at a boarding school with colonial roots. She rebuilt those memories with collage and animation, and the film screened at the London Short Film Festival and the Oberhausen International Short Film Festival in 2022. In 2023 she was selected for Berlinale Talents, the Berlin International Film Festival's programme for emerging filmmakers."),

("h2", "Why watch her", "Remember ", "the name"),
("p", "A feature documentary can take years to reach a screen, and <em>The Ones With the Tempered Flowers</em> is still at the development stage. But eight awards before a finished cut is a strong start, and the 2027 market places it has won put it in the rooms where documentaries find their partners."),
("p", "If you want to follow the journey, Ngelime is on Instagram at <a href=\"https://www.instagram.com/thebongolese/\" target=\"_blank\" rel=\"noopener\">@thebongolese</a>."),
]

